interface User { id: string; name: string; }

async function loadUsers(): Promise<User[]> {
  const res = await fetch('/api/users');
  const raw: unknown = await res.json();
  if (!Array.isArray(raw)) throw new Error('expected array');
  return raw.filter(isUser);
}

function isUser(x: unknown): x is User {
  return typeof x === 'object' && x !== null &&
    'id' in x && typeof (x as User).id === 'string' &&
    'name' in x && typeof (x as User).name === 'string';
}

// C# serializes Dictionary<string, int> as JSON object
const json = '{"ada": 95, "linus": 88}';

// Record for JSON-shaped dict
type ScoreMap = Record<string, number>;
const scores: ScoreMap = JSON.parse(json); // still unsafe — validate

// Map for runtime mutations with non-string keys
const cache = new Map<object, ScoreMap>();

function sum(nums: readonly number[]): number {
  return nums.reduce((a, b) => a + b, 0);
}

// C# IReadOnlyList<int> would throw on Add at runtime
// TS readonly — caller can still mutate original if they keep mutable ref:
const data = [1, 2, 3];
sum(data);
data.push(4); // still works at runtime

type OrderDto = { items: { sku: string; qty: number }[] };

